// Generate student progress report
const grades = $input.all().map(item => item.json);
const now = new Date();
const weekStart = new Date(now.getTime() - 7 * 86400000);

// Filter grades from this week
const weeklyGrades = grades.filter(g => {
  const gradedDate = new Date(g.graded_at || g.date);
  return gradedDate >= weekStart;
});

// Group by student
const studentProgress = {};

weeklyGrades.forEach(grade => {
  const email = grade.student_email;
  if (!studentProgress[email]) {
    studentProgress[email] = {
      name: grade.student_name,
      email,
      quizzes: [],
      total_score: 0,
      count: 0
    };
  }

  studentProgress[email].quizzes.push({
    score: parseFloat(grade.score) || 0,
    grade: grade.grade,
    passed: grade.passed === true || grade.passed === 'true',
    date: grade.graded_at
  });

  studentProgress[email].total_score += parseFloat(grade.score) || 0;
  studentProgress[email].count++;
});

// Calculate averages
const students = Object.values(studentProgress).map(student => ({
  ...student,
  average_score: student.count > 0 ? (student.total_score / student.count).toFixed(1) : 0,
  average_grade: student.count > 0 ? 
    (student.total_score / student.count >= 90 ? 'A' :
     student.total_score / student.count >= 80 ? 'B' :
     student.total_score / student.count >= 70 ? 'C' :
     student.total_score / student.count >= 60 ? 'D' : 'F') : 'N/A',
  pass_rate: student.count > 0 ? 
    ((student.quizzes.filter(q => q.passed).length / student.count) * 100).toFixed(0) : 0,
  quiz_count: student.count
}));

console.log(`Generated progress for ${students.length} students`);

return [{
  json: {
    students,
    total_students: students.length,
    week_ending: now.toISOString().split('T')[0],
    generated_at: now.toISOString(),
    timezone: 'Asia/Ho_Chi_Minh'
  }
}];

// Format progress report email
const report = $input.first().json;

const studentSummaries = report.students.map((s, i) => {
  const status = parseFloat(s.average_score) >= 50 ? '✅' : '⚠️';
  return `${status} ${i + 1}. ${s.name}
   Điểm TB: ${s.average_score}% | Đánh giá: ${s.average_grade}
   Số quiz: ${s.quiz_count} | Tỷ lệ đạt: ${s.pass_rate}%`;
}).join('\n\n');

const emailBody = `Chào team,

Đây là báo cáo tiến độ học tập tuần kết thúc ngày ${report.week_ending}:

━━━━━━━━━━━━━━━━━━━━
📊 TỔNG QUAN
━━━━━━━━━━━━━━━━━━━━

Tổng học sinh: ${report.total_students}

━━━━━━━━━━━━━━━━━━━━
📈 CHI TIẾT THEO HỌC SINH
━━━━━━━━━━━━━━━━━━━━

${studentSummaries}

━━━━━━━━━━━━━━━━━━━━

Xem chi tiết tại Google Sheets.

Trân trọng,
Hệ thống Quản lý Học tập`;

return [{
  json: {
    to: '', // Điền email giảng viên/quản lý
    subject: `📊 Báo cáo Tiến độ Tuần - ${report.week_ending}`,
    body: emailBody,
    report_data: report
  }
}];
